BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "Projects" (
	"id"	INTEGER,
	"prj_id"	INTEGER NOT NULL,
	"description"	TEXT,
	PRIMARY KEY("id"),
	UNIQUE("prj_id")
);
CREATE TABLE IF NOT EXISTS "Reports" (
	"id"	INTEGER,
	"userid"	INTEGER NOT NULL,
	"prj_id"	INTEGER NOT NULL,
	"description"	TEXT,
	"mission_on"	BLOB DEFAULT FALSE,
	"mission_place"	TEXT,
	"mission_road"	BLOB DEFAULT FALSE,
	"start_time"	DATETIME,
	"end_time"	DATETIME,
	"disable"	BLOB DEFAULT FALSE,
	"timestamp"	DATETIME DEFAULT CURRENT_TIMESTAMP,
	"work_type"	INTEGER DEFAULT 0,
	PRIMARY KEY("id"),
	UNIQUE("userid","start_time")
);
CREATE TABLE IF NOT EXISTS "Users" (
	"id"	INTEGER,
	"username"	TEXT NOT NULL,
	"longname"	TEXT,
	"city"	TEXT NOT NULL,
	"email"	TEXT NOT NULL,
	"password"	TEXT NOT NULL DEFAULT 'popnr',
	"is_admin"	BLOB DEFAULT FALSE,
	"is_blocked"	BLOB DEFAULT FALSE,
	PRIMARY KEY("id"),
	UNIQUE("username")
);
CREATE TABLE IF NOT EXISTS "Vacations" (
	"id"	INTEGER,
	"userid"	INTEGER,
	"date_start"	date,
	"date_end"	date,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "WorkTypes" (
	"id"	INTEGER,
	"name"	TEXT NOT NULL,
	"calculate_hours"	BLOB DEFAULT 0,
	PRIMARY KEY("id" AUTOINCREMENT)
);
